user_name = "演示用户"

products = [
(1, 'HKT-SPL系列球面剖分轴承', '面议', 'HKT调心滚子剖分轴承', '/media/products/131.png', '整体式球面滚子轴承通常与剖分式SN/SD轴承座一起使用，由于轴承座已剖分，虽然方便，但装拆内部整体轴承时，由于需要拆除周边临近零部件，因此拆装依然极为困难，时间也比较长。 HKT轴承SPL系列剖分轴承无需对现有的轴承座进行改造，可直接替代整体式球面滚子轴承，特别针对位置受限，难于装拆，对停机时间有要求的位置。'),
(2, 'HKT圆柱滚子剖分轴承', '面议', 'HKT圆柱剖分轴承', '/media/products/130.png', '剖分轴承的完全可分离性，决定了在安装、拆卸轴承时不需移除周边设备，更换方便，减少停机时间，降低停机成本，提高生产效率，增加生产效益。 可随时检查轴承的运行状况（只需拆开轴承座顶盖、轴承箱和外圈，即可对整个轴承作检查）。 不需要专用的安装或拆卸的工具，仅仅内六角扳手。 拆卸轴承时对轴承没有任何损伤，避免了因其它零部件不可换需拆卸轴承时对轴承的破坏，从实际意义上延长了轴承寿命，减少备件费用。'),
(3, '深沟球轴承', '面议', 'NTN轴承', '/media/products/60.jpg', '深沟球轴承是滚动轴承中最为普通的一种类型。基本型的深沟球轴承由一个外圈，一个内圈、一组钢球和一组保持架构成。 深沟球轴承类型有单列和双列两种，深沟球结构还分密封和开式两种结构，开式是指轴承不带密封结构，密封型深沟球分为防尘密封和防油密封。'),
(4, '圆柱滚子轴承', '面议', 'NTN轴承', '/media/products/64.jpg', '滚动体是圆柱滚子的向心滚动轴承。圆柱滚子轴承内部结构采用滚子呈90°相互垂直交叉排列（这也是交 叉滚子轴承的名称由来），滚子之间装有间隔保持器或者隔离块，可以防止滚子的倾斜或滚子之间相互磨察，有效防止了旋转扭矩的增加。'),
(5, '角接触球轴承', '面议', 'NTN轴承', '/media/products/58.jpg', '(Angular Contact Ball Bearings)可同时承受径向负荷和轴向负荷。能在较高的转速下工作。接触角越大，轴向承载能力越高。高精度和高速轴承通常取15 度接触角。在轴向力作用下，接触角会增大。'),
(6, '调心球轴承', '面议', 'NTN轴承', '/media/products/62.jpg', '调心球轴承有圆柱孔和圆锥孔两种结构，保持架的材质有钢板、合成树脂等。其特点是外圈滚道呈球面形，具有自动调心性，可以补偿不同心度和轴挠度造成的误差，但其内、外圈相对倾斜度不得超过3度。'),
(7, '调心滚子轴承', '面议', 'NTN轴承', '/media/products/61.jpg', '调心滚子轴承具有两列滚子，主要承受径向载荷，同时也能承受任一方向的轴向载荷。有高的径向载荷能力，特别适用于重载或振动载荷下工作，但不能承受纯轴向载荷。该类轴承外圈滚道是球面形，故其调心性能良好，能补偿同轴度误差。'),
(8, '圆锥滚子轴承', '面议', 'NTN轴承', '/media/products/65.jpg', '圆锥滚子轴承属于分离型轴承，轴承的内、外圈均具有锥形滚道。该类轴承按所装滚子的列数分为单列、双列和四列圆锥滚子轴承等不同的结构型式。单列圆锥滚子轴承可以承受径向负荷和单一方向轴向负荷。当轴承承受径向负荷时，将会产生一个轴向分力，所以当需要另一个可承受反方向轴向力的轴承来加以平衡。'),
(9, '精密滚动轴承', '面议', 'NTN轴承', '/media/products/59.jpg', '精密轴承按照ISO的分级标准分为：P0,P6,P5,P4,P2.等级依次增高，其中P0为普通精度， 其他等级都是精密级别。当然，不同分级标准，不同类型的轴承，他们的分级方法有所不同的，但意义是一至的。精密轴承使用性能上要求旋转体具有高跳动精度、高速旋转及要求摩擦及摩擦变化小。'),
(10, '推力球轴承', '面议', 'NTN轴承', '/media/products/63.jpg', '推力球轴承采用高速运转时可承受推力载荷的设计，由带有球滚动的滚道沟的垫圈状套圈构成。由于套圈为座垫形，因此，推力球轴承被分为平底座垫型和调心球面座垫型两种类型。另外，这种轴承可承受轴向载荷，但不能承受径向载荷。'),
(11, '滚针轴承', '面议', 'NTN轴承', '/media/products/57.jpg', '滚针轴承(needle bearing)是带圆柱滚子的滚子轴承，相对其直径，滚子既细又长。这种滚子称为滚针。尽管具有较小的截面，轴承仍具有较高的负荷承受能力，滚针轴承装有细而长的滚子（滚子直径D≤5mm，L/D≥2.5，L为滚子长度），因此径向结构紧凑，其内径尺寸和载荷能力与其它类型轴承相同时，外径最小，特别适用于径向安装尺寸受限制的支承结构。'),
(12, '带座外球面轴承', '面议', 'NTN轴承', '/media/products/56.jpg', '带座外球面轴承(insert bearing with housing)是将滚动轴承与轴承座结合在一起的一种轴承单元。大部分外球面轴承都是将外径做成球面，与带有球状内孔的进口轴承座安装在一起，结构形式多样，通用性和互换性好。'),
(13, '回转支撑轴承', '面议', '特种轴承', '/media/products/49.png', '回转支承是一种能够承受综合载荷的大型轴承，可以同时承受较大的轴向、径向负荷和倾覆力矩。 回转支承又叫转盘轴承，有些人也称其为：旋转支承、 回旋支承。 英文名字分别叫: slewing bearing 、 slewing ring bearing 、 turntable bearing、slewing ring。 回转支承在现实工业中应用很广泛，被人们称为：“机器的关节”，是两物体之间需作相对回转运动，又需同时承受轴向力、径向力、倾翻力矩的机械所必需的重要传动部件。随着机械行业的迅速发展，回转支承在船舶设备、工程机械、轻工机械、冶金机械、医疗机械、工业机械等行业得到了广泛的应用。'),
(14, '球面滚子轴承', '面议', 'SKF轴承', '/media/products/70.jpg', '球面滚子轴承具有两列滚子，主要承受径向载荷，同时也能承受任一方向的轴向载荷。有高的径向载荷能力，特别适用于重载或振动载荷下工作，但不能承受纯轴向载荷。该类轴承外圈滚道是球面形，故其调心性能良好，能补偿同轴度误差。'),
(15, '自调心球轴承', '面议', 'SKF轴承', '/media/products/77.jpg', '自调心球轴承有圆柱孔和圆锥孔两种结构，保持架的材质有钢板、合成树脂等。其特点是外圈滚道呈球面形，具有自动调心性，可以补偿不同心度和轴挠度造成的误差，但其内、外圈相对倾斜度不得超过3度。'),
(16, '轴承座', '面议', 'SKF轴承', '/media/products/76.jpg', 'SKF SNL轴承座的设计主要用于负荷垂直作用在支承面上的应用，在这种情况下，轴承座能承受的负荷是完全取决于轴承的承载能力。如果负荷是作用在另一个方向，则必须检查轴承座、连接轴承座顶盖和底座的螺栓、以及地肢联接螺栓的承受能力。SNL轴承座一般由灰口铸铁制成。如果在某些应用需要更高强度的铸铁，可以选用球墨铸铁制成并有相同尺寸的轴承座。'),
(17, '圆锥滚子轴承', '面议', 'SKF轴承', '/media/products/75.jpg', '圆锥滚子轴承属于分离型轴承，轴承的内、外圈均具有锥形滚道。该类轴承按所装滚子的列数分为单列、双列和四列圆锥滚子轴承等不同的结构型式。单列圆锥滚子轴承可以承受径向负荷和单一方向轴向负荷。当轴承承受径向负荷时，将会产生一个轴向分力，所以当需要另一个可承受反方向轴向力的轴承来加以平衡。'),
(18, '圆柱滚子轴承', '面议', 'SKF轴承', '/media/products/74.jpg', '滚动体是圆柱滚子的向心滚动轴承。圆柱滚子轴承内部结构采用滚子呈90°相互垂直交叉排列（这也是交 叉滚子轴承的名称由来），滚子之间装有间隔保持器或者隔离块，可以防止滚子的倾斜或滚子之间相互磨察，有效防止了旋转扭矩的增加。'),
(19, '圆柱滚子推力轴承', '面议', 'SKF轴承', '/media/products/73.jpg', '这种轴承可以承受单方向很大的轴向载荷，但是不能承受径向载荷，它们没有自动调心能力。 推力圆柱滚子轴承可以拆分为推力圆柱滚子和保持架组件、轴圈和座圈。 811系列和812系列推力圆柱滚子轴承由推力圆柱滚子和保持架组件、轴圈和座圈组成，最重要的零部件是推力圆柱滚子和保持架组件。'),
(20, '角接触球轴承', '面议', 'SKF轴承', '/media/products/72.jpg', '(Angular Contact Ball Bearings)可同时承受径向负荷和轴向负荷。能在较高的转速下工作。接触角越大，轴向承载能力越高。高精度和高速轴承通常取15 度接触角。在轴向力作用下，接触角会增大。 SKF任意配对轴承以三种不同游隙和预载荷等级生产。 带游隙的轴承组的等级为： – CA轴向游隙小于普通组； – CB普通级轴向游隙（普通级）； – CC轴向游隙大于普通组。 带CB游隙级的轴承为标准轴承，而一些较大的轴承带G级游隙。 带游隙的SKF任意配对轴承可结合在包括任何数量轴承的轴承组中。 带预载荷的轴承组的等级为： – GA轻型预载荷（标准）； – GB中型预载荷； – GC重型预载荷。 带GA级预载荷的轴承为标准轴承。同带游隙的SKF任意配对轴承相比，带预载荷的轴承只能以两个轴承成组配对，否则预载荷会增加。'),
(21, '球面滚子推力轴承', '面议', 'SKF轴承', '/media/products/69.jpg', '推力调心滚子轴承与调心滚子轴承同样，座圈滚道面是以与轴承中心轴上一致的点为中心的球面，该类轴承滚子为球面型，因此，具有自动调心功能，对同轴度和轴的挠曲不甚敏感。'),
(22, '高精密角接触球轴承', '面议', 'SKF轴承', '/media/products/68.jpg', '精密轴承按照ISO的分级标准分为：P0,P6,P5,P4,P2.等级依次增高，其中P0为普通精度， 其他等级都是精密级别。当然，不同分级标准，不同类型的轴承，他们的分级方法有所不同的，但意义是一至的。精密轴承使用性能上要求旋转体具有高跳动精度、高速旋转及要求摩擦及摩擦变化小。'),
(23, '低能效深沟球轴承', '面议', 'SKF轴承', '/media/products/71.jpg', '通过优化内部几何形状和所有接触面的表面光洁度、重新设计保持架、结合极纯净和匀质的钢材与独特的热处理技术、并提高钢球的质量和一致性，使SKF 探索者接触球轴承在性能方面实现了显著改进。 SKF Explorer探索者深沟球轴承具有出色的性能，特别适合电机、两轮摩托车和传动装置等应用。 这些性能提高具有如下益处： 更高的动态承载能力 降低噪音和振动水平 减少摩擦热量 显著延长轴承的使用寿命 这种轴承通过设计的优化，降低轴承的能耗，从而降低对环境的影响。 同样重要的是，SKF Explorer探索者轴承可减少维修并有助于提高生产率。 SKF 能效型 (E2) 轴承 为了满足对减少机械磨损和能源消耗日益增长的需求，SKF 开发了 SKF 能效型（E2）性能等级的滚动轴承。 与相同尺寸的 SKF 探索者轴承相比，SKF E2 深沟球轴承摩擦力矩至少减少 30%。 与同类 SKF Explorer探索者深沟球轴承相比，SKF E2 深沟球轴承的寿命更长且润滑剂消耗更少。'),
(24, 'Y轴承单元', '面议', 'SKF轴承', '/media/products/67.jpg', 'Y 轴承通常指插入型轴承，是根据 62 和 63 系列的密封型深沟球轴承设计，但带有一个凸外圈，且在大多数情况下，内圈宽度延伸，带有一定的锁定装置，能够快速方便地安装到轴。 Y 轴承以单个或单元供应。 Y 轴承单元包括轴承座、轴承和在工厂经过预装及脂润滑的密封件。 这些快装单元能够承受一定程度的初始不对中，但通常不能造成轴上的轴向位移。 Y 轴承和 Y 轴承单元提供一种简单、高效的解决方案，具有很多优势。'),
(25, 'CARB圆环滚子轴承', '面议', 'SKF轴承', '/media/products/66.jpg', 'CARB圆环滚子轴承是一种全新的径向滚子轴承。 这种紧凑型自调心滚子轴承是SKF于1995年面市。该轴承设计独特， 结合了球面滚子轴承的自调心能力与圆柱滚子轴承的无限制轴向位移能力。 它还可以具有较小的横截面积，而通常滚针轴承才具备这一特征。'),
(26, 'COOPER剖分轴承', '面议', 'COOPER剖分轴承', '/media/products/50.jpg', '主要特点:轴承内、外圈、保持架密封完全剖分,便于拆装. • 解决用户安装、拆卸时的烦恼，极大的方便安装、拆卸，节约大量的时间，并显著节约生产费用。 • 应用场合:拆装非常困难的工况 -多点支撑轴系 -曲轴 -受空间限制难以拆装的工况'),
(27, '角接触球轴承', '面议', 'FAG轴承', '/media/products/86.jpg', '(Angular Contact Ball Bearings)可同时承受径向负荷和轴向负荷。能在较高的转速下工作。接触角越大，轴向承载能力越高。高精度和高速轴承通常取15 度接触角。在轴向力作用下，接触角会增大。'),
(28, '深沟球轴承', '面议', 'FAG轴承', '/media/products/85.jpg', '深沟球轴承是滚动轴承中最为普通的一种类型。基本型的深沟球轴承由一个外圈，一个内圈、一组钢球和一组保持架构成。 深沟球轴承类型有单列和双列两种，深沟球结构还分密封和开式两种结构，开式是指轴承不带密封结构，密封型深沟球分为防尘密封和防油密封。'),
(29, '推力球轴承', '面议', 'FAG轴承', '/media/products/84.jpg', '推力球轴承采用高速运转时可承受推力载荷的设计，由带有球滚动的滚道沟的垫圈状套圈构成。由于套圈为座垫形，因此，推力球轴承被分为平底座垫型和调心球面座垫型两种类型。另外，这种轴承可承受轴向载荷，但不能承受径向载荷。'),
(30, '推力调心滚子轴承', '面议', 'FAG轴承', '/media/products/83.jpg', '推力调心滚子轴承与调心滚子轴承同样，座圈滚道面是以与轴承中心轴上一致的点为中心的球面，该类轴承滚子为球面型，因此，具有自动调心功能，对同轴度和轴的挠曲不甚敏感。'),
(31, '圆柱滚子轴承', '面议', 'FAG轴承', '/media/products/82.jpg', '滚动体是圆柱滚子的向心滚动轴承。圆柱滚子轴承内部结构采用滚子呈90°相互垂直交叉排列（这也是交 叉滚子轴承的名称由来），滚子之间装有间隔保持器或者隔离块，可以防止滚子的倾斜或滚子之间相互磨察，有效防止了旋转扭矩的增加。'),
(32, '调心滚子轴承', '面议', 'FAG轴承', '/media/products/81.jpg', '调心滚子轴承具有两列滚子，主要承受径向载荷，同时也能承受任一方向的轴向载荷。有高的径向载荷能力，特别适用于重载或振动载荷下工作，但不能承受纯轴向载荷。该类轴承外圈滚道是球面形，故其调心性能良好，能补偿同轴度误差。'),
(33, '圆锥滚子轴承', '面议', 'FAG轴承', '/media/products/80.jpg', '圆锥滚子轴承属于分离型轴承，轴承的内、外圈均具有锥形滚道。该类轴承按所装滚子的列数分为单列、双列和四列圆锥滚子轴承等不同的结构型式。单列圆锥滚子轴承可以承受径向负荷和单一方向轴向负荷。当轴承承受径向负荷时，将会产生一个轴向分力，所以当需要另一个可承受反方向轴向力的轴承来加以平衡。 四列圆锥滚子轴承成功地使用在轧钢速度为低速至中速的世界各地轧钢机的轴承配置中。由于其设计，这种轴承能够在径向载荷之外承受出现在这种应用场合中的轴向载荷，一般来说在轴承配置中不需要另外的推力轴承。这意味着轧辊轴颈可相对较短，而且轧辊两侧的轴承座可采用相同设计由于四列圆锥滚子轴承的设计，这种轴承必须作为完整轴承安装在轧辊轴承座上。为了能够快速更换轧辊，这种轴承在轧辊轴颈上必须松配合。松配合的缺点是内圈在主载荷条件下在其基座上蠕动，通常会引起硬度比轴承圈低的基座的磨损。为了在一定程度上减少松配合的影响，即降低磨损，轴承在内圈孔中有螺旋槽，而且/或在内圈侧面有油槽。这些油槽把润滑剂送到内圈和基座的接触表面上。此外，填充油脂的槽可吸收磨损颗粒。'),
(34, '主轴轴承', '面议', 'FAG轴承', '/media/products/79.jpg', '机床主轴轴承是精密机床及类似设备的主轴轴承，它对保证精密机床的工作精度和使用性能。 主轴轴承的正确配置是指轴承类型的组合和前后轴承的布置,不同的配置就决定了机床主轴不同的负荷能力、运转速度、刚度、温升和使用寿命,尤其是对刚度和温升的影响更为显著〔注 〕,所以应根据机床工作特性的要求合理地配置主轴轴承。跑合运转的目的是为了使轴承在正式使角前,使其滚子与滚道通过跑合,能具有良好的接触条件,以保持轴承有良好的接触精度,并避免轴承一开始在高速和重载使用时引起滚子与滚道的损坏,从而提高了轴承的寿命和精度。'),
(35, '自调心球轴承', '面议', 'FAG轴承', '/media/products/78.jpg', '调心球轴承有圆柱孔和圆锥孔两种结构，保持架的材质有钢板、合成树脂等。其特点是外圈滚道呈球面形，具有自动调心性，可以补偿不同心度和轴挠度造成的误差，但其内、外圈相对倾斜度不得超过3度。'),
(36, '调心滚子轴承', '面议', 'ROLLWAY轴承', '/media/products/99.jpg', '调心滚子轴承具有两列滚子，主要承受径向载荷，同时也能承受任一方向的轴向载荷。有高的径向载荷能力，特别适用于重载或振动载荷下工作，但不能承受纯轴向载荷。该类轴承外圈滚道是球面形，故其调心性能良好，能补偿同轴度误差。'),
(37, '圆柱滚子轴承', '面议', 'ROLLWAY轴承', '/media/products/98.jpg', '滚动体是圆柱滚子的向心滚动轴承。圆柱滚子轴承内部结构采用滚子呈90°相互垂直交叉排列（这也是交 叉滚子轴承的名称由来），滚子之间装有间隔保持器或者隔离块，可以防止滚子的倾斜或滚子之间相互磨察，有效防止了旋转扭矩的增加。'),
(38, '深沟球轴承', '面议', 'ROLLWAY轴承', '/media/products/97.jpg', '深沟球轴承是滚动轴承中最为普通的一种类型。基本型的深沟球轴承由一个外圈，一个内圈、一组钢球和一组保持架构成。 深沟球轴承类型有单列和双列两种，深沟球结构还分密封和开式两种结构，开式是指轴承不带密封结构，密封型深沟球分为防尘密封和防油密封。'),
(39, '推力球面轴承', '面议', 'ROLLWAY轴承', '/media/products/96.jpg', '推力调心滚子轴承与调心滚子轴承同样，座圈滚道面是以与轴承中心轴上一致的点为中心的球面，该类轴承滚子为球面型，因此，具有自动调心功能，对同轴度和轴的挠曲不甚敏感。'),
(40, '圆锥滚子轴承', '面议', 'ROLLWAY轴承', '/media/products/95.jpg', '圆锥滚子轴承属于分离型轴承，轴承的内、外圈均具有锥形滚道。该类轴承按所装滚子的列数分为单列、双列和四列圆锥滚子轴承等不同的结构型式。单列圆锥滚子轴承可以承受径向负荷和单一方向轴向负荷。当轴承承受径向负荷时，将会产生一个轴向分力，所以当需要另一个可承受反方向轴向力的轴承来加以平衡。'),
(41, '带座球轴承', '面议', '通用轴承', '/media/products/92.jpg', '带座球轴承采用密封和润滑的一体化设计，公制和英制产品提供多种可选的轴承座，锁紧类型和安装方式，保证旋转轴的径向力承载同时提供很好的抗磨损解决方案。'),
(42, '带座圆锥滚子轴承', '面议', '通用轴承', '/media/products/91.jpg', '模块化轴承组件，带有密封和润滑的圆锥滚子轴承，采用国定螺钉锁定，有多种轴承座材料、类型和安装型式可供选择，带座圆锥滚子轴承为承受径向和轴向组合载荷和低摩擦提供很好的解决方案。'),
(43, '带座球面滚子轴承', '面议', '通用轴承', '/media/products/90.jpg', '带座球面滚子轴承采用密封润滑一体化设计，配有锁环锁紧（紧定螺钉）或同心锁紧（紧定套），英制产品提供多种可选的轴承座，安装方式和座体材料，保证旋转轴的径向力和轴向力承载同时提供很好的抗磨损解决方案。'),
(44, 'KRG系列限矩型液力偶合器', '面议', '限矩型液偶', '/media/products/17.png', '特点： 结构简单，经济实用 启动时提供限矩保护 大惯量设备实现柔性启动 具有很好的扭振吸收能力 可使用更经济的鼠笼电机 外壳及内轮采用优质的原生铝铸造 采用优质的轴承和密封 防止油液泄露'),
(45, '限矩型液偶CKDM--可径向拆卸型', '面议', '限矩型液偶', '/media/products/19.png', '特点： 采用在膜片联轴器，可实现不移动 电机和减速机的情况下，快速径向 拆卸液力耦合器'),
(46, '调速型液力偶合器NVC系列', '面议', '调速型液偶', '/media/products/18.jpg', 'NVC型特点： 水平整体结构，自支撑设计 内置供油泵 可持续润滑的抗磨损轴承 配有油液冷却系统 可远程或自动控制 调速范围可达25-100% 最大功率可达6000KW 主要应用： －锅炉给水泵 －离心泵 －风机 －皮带输送机 －搅拌机、粉碎机 －测试工作设备'),
(47, 'NARA链式联轴器', '面议', '链式联轴器', '/media/products/118.jpg', '链式联轴器 滚子链联轴器（又叫齿链式联轴器） · 结构简单，安装方便 · 反转时有空行程，不宜用于冲击载荷特别大的场合 · 有带保护壳的型号，主要用于高转速和潮湿环境场合 · 应用范围极其广泛.'),
(48, 'NARA卷筒联轴器', '面议', '卷筒联轴器', '/media/products/117.jpg', '卷筒联轴器用于减速机轴和起重机钢丝绳卷筒之间的连接。 卷筒联轴器的应用，消除了卷筒在部件装配期间因刚性连接而较难对正的缺陷。当不同心的减速机轴承受高弯矩时，会对应力集中的支撑部分造成磨损，并将损坏轴承和齿轮。由于安装时间长，维修困难，停机时间长，费用也将随之增加。 而卷筒联轴器使避免上述的所有缺点变为可能，所需支撑可因此削减1/3，并能有效补偿安装和装配过程中产生的不同心度。 滚筒安装于坚实的基座上，并允许承受高径向载荷，确保高度持续的可靠性至关重要。 经许可的简化设计，只需安装衬套和轮毂到各自的部件上，沿轴向将它们移到一起，即可在减速机和卷筒间实现消除扭振的连接。'),
(49, '鼓型齿联轴器', '面议', '齿形联轴器', '/media/products/3.png', '鼓型齿联轴器特点 鼓形齿式联轴器属于刚挠性联轴器 具有径向、轴向和角向等轴线偏差补偿能力 与直齿式联轴器相比，具有结构紧凑、回转半径小、承载能力大、传动效率高、噪声低及维修周期长等优点 特别适用于低速重载工况，如冶金、矿山、起重运输等行业 也适用于石油、化工、通用机械等各类机械的轴系传动'),
(50, '金属碟片联轴器', '面议', '膜片联轴器', '/media/products/5.png', '碟片式联轴器可补偿轴向，角度和径向偏差。一般它们具有如下优点： 无需润滑和维护 检查时无需拆卸联轴器 用闪光灯可以在机器运转情况下检查碟片状况 机器设备的偏差可评估 刚性扭力无侧隙 无磨损部件，对恶劣环境具有强抵抗力 如果良好对中，使用寿命将比较长'),
(51, '梅花联轴器', '面议', '梅花联轴器', '/media/products/14.png', 'JAUFLEX 梅花联轴器 JAUFLEX 联轴器应用弹性体元件，并提供所需的扭转弹性以达到平稳的扭矩传递。 通过准确的弹性元件类型及联轴器型号的选取，所有在从动轴的冲击或扭转震动都可以避免。 JAUFLEX 联轴器的主要特点： －补偿径向，角度和轴向偏差 －相对较小的尺寸和重量 －具有少量的残余不平衡，因为它是加工出来的以及弹性元件很轻且准确成型,可实现进一步的平衡 －轴套卡盘的光滑表面确保了弹性体元件的长寿命 －无需润滑，低维护 －固有的电绝缘性，因为两个轴套间没有金属间的接触'),
(52, '蛇形弹簧联轴器', '面议', '蛇形簧联轴器', '/media/products/23.jpg', '蛇形弹簧联轴器特点 可与其他蛇形弹簧联轴器替换 水平分离，铝合金端盖 简便安装为整套蛇形弹簧 在指定空间内装配简便 吸收中等冲击和震动载荷，扭转灵活 适于可逆服务 内六角有头螺钉，和自锁螺母 快速，简便安装，低维护'),
(53, 'simrit丁晴橡胶油封', '面议', 'SKF油封', '/media/products/111.jpg', '型号: BAUX2, BAUSLX2, BAFUDSLX7, BA, BASL, BAU, BAUSL 材料: Simrit 72 NBR 902 1. 特点 ■ 油封外缘：橡胶包覆（光滑或带槽X7型） ■ 密封唇装有弹簧 ■ 附有防尘唇 （BA…SL型） ■ 密封唇前端面由机加工而成。（优化设计的油封型号 BAUX2 和BAUSLX2） ■ 密封唇模压加工完成 （BAFUDX7/BAFUDSLX7型） 2. 材料 丁腈橡胶 代号:72 NBR 902 颜色: 蓝色 硬度: 邵式A 75度 金属骨架: 非合金钢 DIN 1624 弹簧: 弹簧钢DIN 1722 3. 优点 ■ 广泛应用于普通工业的各个领域 ■ 油封外缘密封可靠，即便是座孔内园面的粗糙度大或有热膨胀以及采用开式腔体，亦可以密封低粘度的介质和气体。 ■ 附有防尘唇，防止一般和中等程度的尘埃污染以及脏物 从外界侵入（BA…SL型）（注：会引起温度升高，由于摩擦生热） 4.推荐应用 ■工业变速箱 ■轮轴（仅限中等程度以内的污染） ■电动工具'),
(54, 'simrit氟橡胶油封', '面议', 'SKF油封', '/media/products/112.jpg', '型号: BAUMX7, BAUMSLX7, BAUM, BAUMSL 材料: Simrit 75 FKM 585 1. 特点 ■油封外缘：橡胶包覆（光滑或带槽X7型） ■密封唇装有弹簧 ■附有防尘唇 （BAUMSL, BAUMSLX7型） ■优化设计的密封唇唇部截面结构 2. 材料 氟橡胶 代号:75 FKM 585 颜色: 深棕色 硬度: 邵式A 75度 金属骨架: 非合金钢 DIN EN 10027-1 弹簧: 弹簧钢DIN EN 10270 3. 优点 ■广泛应用于普通工业的各个领域 ■较高的耐热稳定性和耐化学介质稳定性 ■油封外缘密封可靠，即便是座孔的粗糙度大或有热膨胀以及采用开式腔体 ■密封低粘度介质和气体有优势 ■附有防尘唇，防止一般和中等程度的尘埃污染以及脏物从外界侵入（BAUMSLX7 型） （注：会引起温度升高，由于摩擦生热） 4.推荐应用 ■农业机械及工程机械传动部件 ■工业变速箱 ■轮轴（适用中等程度以下的污染） ■动力设备'),
(55, 'SOG丁晴橡胶油封', '面议', 'SOG油封', '/media/products/113.jpg', '台湾SOG丁晴橡胶骨架油封'),
(56, 'SOG氟橡胶油封', '面议', 'SOG油封', '/media/products/114.jpg', 'SOG氟橡胶骨架油封'),
(57, 'SKF电机轴承润滑脂', '面议', 'SKF润滑脂', '/media/products/121.jpg', '专业的电机轴承润滑脂-LGHP 2 SKF LGHP 2是一种以矿物油为基础油的优质润滑脂，使 用聚脲（双脲）稠化剂。它适用于要求运行极其安静的 环境，其工作温度为–40 °C到150 °C宽温，中速至高速 条件下运行的球轴承。 这种润滑脂具有以下特点: *高温下寿命长 *适用温度范围大 *优越的耐腐蚀性 *热稳定性高 *良好的低温启动性 *可与锂复合基增稠剂润滑脂兼容使用 典型应用： 电机：小型、中型和大型 工业风机，包括高速风机 水泵 纺织、纸加工和干燥机器中的滚动轴承 在中温和高温下运行的中高速球轴承(和辊子轴承) 离合器分离轴承 垂直轴应用 窑车和辊子 行业：钢铁、矿山、水泥、电力、造船、油田、化工等大型电机轴承 可提供的LGHP 2包装形式 SYSTEM 24 420毫升 1公斤 5公斤 18公斤 50公斤 180公斤'),
(58, 'SKF工业通用轴承润滑脂', '面议', 'SKF润滑脂', '/media/products/123.jpg', 'SKF工业和汽车通用轴承润滑脂 LGMT 3是以矿物油为基础油的锂基润滑脂，在工业和汽车上有广泛的应用。 很好的防锈特性 在推荐温度范围内具有高氧化安定性 典型应用： 轴承内径 >100 mm 外圈旋转的轴承 垂直轴应用 环境温度持续 >35 °C 螺旋桨轴 农业机械 轿车、卡车和拖车轮毂轴承 大型电机 技术参数 订货号LGMT 3/(包装规格) DIN 51825代码 K3K-30 NLGI稠度等级 3 皂基类型 锂基 颜色 琥珀色 基础油类型 矿物油 工作温度范围 –30至+120 °C 滴点DIN ISO 2176 >180 °C 基础油粘度 40 °C, mm2/s 120–130 100 °C, mm2/s 12 锥入度DIN ISO 2137 60次剪切，10–1 mm 220–250 100 000次剪切，10–1 mm 最大280 机械稳定性 滚筒实验，在80 °C下50小时， 最大295 包装规格 420 ml 0.5kg, 1kg, 5kg, 18kg, 50kg, 180kg'),
]

news = [
(1, '中石化高管：炼油产能过剩 应建预警机制', '2015-03-11', '行业新闻', '中石化高管：炼油产能过剩 应建预警机制', '据初步统计，2014年底我国炼油一次加工能力7.4亿吨左右，预计到2015年底将达到7.6～7.8亿吨；参照国家发布的《石化产业规划布局方案》明确开工建设和规划炼油项目及地方炼油企业扩能等，预计到2020年国内炼油一次加工能力有可能突破9.0亿吨。\n\n全国人大代表，中国石化炼油事业部主任赵日峰说，随着国内经济发展进入新常态，生物燃料及LNG替代、电动车等新兴能源快速发展，成品油市场需求增速放缓，炼油产能已呈现过剩态势。若不加以控制，可能会出现类似钢铁、水泥等行业产能严重过剩的局面。\n\n为避免炼油产能重复无序建设，防止过剩态势恶化，赵日峰建议，国家层面根据国内经济增速、清洁替代能源发展和能源消费结构变化趋势，建立炼油产能预警机制，提出指导性布局意见，合理控制国内炼油一次能力。'),
(2, '煤炭进口量暴跌对国内煤价形成利好 政策是主因', '2015-03-11', '行业新闻', '根据海关总署公布数据显示，今年2月份我国煤炭进口量1526万吨，同比下降33.13%，月环比下降9.06%。今年2月的煤炭单月进口量创下了自2012年以来的月度最低记录。进入2015年以来，1、2月份两月累计进口量为3...', '根据海关总署公布数据显示，今年2月份我国煤炭进口量1526万吨，同比下降33.13%，月环比下降9.06%。今年2月的煤炭单月进口量创下了自2012年以来的月度最低记录。进入2015年以来，1、2月份两月累计进口量为3204万吨，还不及去年1月份单月进口量。另据了解，2015年前两月，作为中俄经贸合作重要通道的绥芬河口岸进口煤炭货值仅4.53万吨，与去年同期相比下降90.96%。由此看来，我国煤炭供过于求的市场坏境有所改善，对国内煤价形成又一利好。\n\n2月份煤炭进口量暴跌已探明：\n\n（1）政策原因\n\n《商品煤质量管理暂行办法》的实施，对于进口煤微量元素施行管控，通关时间周期加长，进口煤风险加大。2月份一批来自朝鲜的进口煤炭因检测出微量元素汞超标而被退运，这也是自1月1日进口煤质检新规实行以来的首例退运案例。此次进口煤质检不合格被退回案例对整个进口煤市场起到一定震慑作用，打击了进口煤贸易商信心。此外，在《商品煤质量管理暂行办法》作用下，进口煤“海进江”被全面控制。导致大部分煤炭进口商观望态度加剧，相应减少从国际市场动力煤采购量。这是2月份煤炭进口量暴跌的主要因素。\n\n（2）需求因素\n\n近期，电力企业煤炭库存居高不下，去库存压力较大。受下游工业用电需求疲软影响，沿海主要电力集团仍有部分发电机组在调停或检修，需求低迷和库存偏高共存的局面导致电力集团采购拉运动力不足，整体上仍以少量的刚性采购为主。\n\n（3）价格因素\n\n目前进口煤业务利润低且风险高，随着国内煤价一路下跌，进口煤和国内煤价差大幅缩小。根据中国煤炭市场网数据显示，截止3月6日，澳洲5500大卡动力煤华南地区港口到岸价（巴拿马船型）下降至480元/吨，环比下降1元/吨，较国内煤华南地区港口到岸价低21元/吨。\n\n根据分析与预测，2015年国内煤炭进口量将会被有效控制，预计全年煤炭进口量将下降至2亿吨左右，降幅为30%-40%。沿海地区煤炭供需形势将基本达到平衡状态，下水煤价企稳回升指日可待。\n\n（作者供职于中国煤炭市场网）'),
(3, '2014年钢铁行业运行情况和2015年展望', '2015-03-11', '行业新闻', '2014年钢铁行业运行情况和2015年展望', '当前,我国经济已进入由高速增长向中高速增长转换的新常态,钢铁行业也随之发生新变化。2014年,钢铁行业化解产能过剩初见成效,企业效益有所好转,节能减排取得新进展。同时,由于下游需求减弱,钢材价格大幅下跌,企业资金紧张凸显等,全行业仍处于转型升级的“阵痛期”,企业面临的生产经营形势依然严峻。\n\n一、2014年钢铁行业运行情况\n\n(一)粗钢产量小幅增长,国内表观消费同比下降。2014年,全国粗钢产量8.2亿吨,同比增长0.9%,增幅同比下降6.6个百分点。国内粗钢表观消费7.4亿吨,同比下降4%;钢材(含重复材)产量11.3亿吨,同比增长4.5%,增幅同比下降6.9个百分点。中国粗钢产量占全球比重为49.4%,同比提高0.9个百分点。\n\n分月份看,全年日均产量225万吨,其中6月份达到231万吨为最高点,11月份211万吨为最低点。分品种看,重轨同比减少5.3%,长材(型钢、棒材、钢筋和线材)同比增长3%,中、厚及特厚板同比增长9.7%,冷热轧板带同比增长2.7%,涂镀板同比增长12.3%,电工钢同比增长5.1%,管材同比增长5.4%。分地区看,产量增速排名前五的省市分别为宁夏、浙江、江苏、陕西和辽宁,增速分别为17.3%、8.8%、7.6%、6.4%、5%;黑龙江、重庆、云南、北京、山西等14个省产量同比有所回落,其中黑龙江、重庆、云南分别回落37.6%、11.6%、10.4%。分企业类型看,2014年,重点大中型钢铁企业粗钢产量6.6亿吨,同比增长1.7%;中小钢铁企业粗钢产量1.7亿吨,同比降低1.8%,占全国粗钢产量比重为20%,同比降低1个百分点。\n\n(二)钢材出口大幅增长,产品档次有所提高。2014年我国出口钢材9378万吨,同比增长50.5%;进口钢材1443万吨,增长2.5%,折合净出口粗钢8153万吨,占我国粗钢总产量的10.2%。从产品档次上看,电工钢板带、涂镀层板带、热轧合金钢板、冷轧薄宽钢带、冷轧不锈钢薄板、锅炉管高附加值产品比例有所提高。\n\n(三)钢材市场供大于求,价格持续下行。近年来,全国钢材价格总体水平不断走低。据统计,重点大中型钢铁企业2011年至2014年全年平均销售结算价格分别为4468元/吨、3750元/吨、3442元/吨、3074元/吨,呈不断下滑趋势。2014年12月末,我国钢材价格综合指数跌至83.1点,同比下降16.2%,为2003年1月以来最低水平。其中三级螺纹钢跌至2791元/吨,较年初下降785元/吨;热轧卷板跌至3131元/吨,较年初下降528元/吨。\n\n(四)铁矿石等原燃料供需格局逆转,价格大幅下降。受国际主要原燃料生产企业生产能力大幅提高及我国钢铁产量增幅下滑影响,2014年钢铁原燃料供需格局逆转,价格大幅下降。62%品位的进口铁矿石到岸价由年初的133.1美元/吨降至年末的68.7美元/吨,下降48%;焦炭由1425元/吨降至893元/吨,下降37%。废钢由2445元/吨降至1928元/吨,下降21%。\n\n(五)生产成本大幅降低,钢铁企业盈利有所好转。2014年,铁矿石、煤炭等大宗原材料价格降幅大于钢材价格,钢铁企业总体经济效益有所起色。重点统计钢铁企业2014年实现利税1091亿元,增长12.2%;盈亏相抵后实现利润304亿元,增长40.4%。但行业销售利润率只有0.9%,仍处于工业行业最低水平。\n\n(六)固定资产投资下降,化解产能过剩矛盾初见成效。2014年,我国钢铁行业固定资产投资6479亿元,同比下降3.8%。其中黑色金属冶炼及压延业投资4789亿元,下降5.9%;黑色金属矿采选业投资1690亿元,增长2.6%。从工序投资增长情况看,炼铁、炼钢和钢压延加工完成投资分别下降40.4%、10.5%和4.8%。从新开工项目情况看,2014年新开工项目2037个,同比减少215个。其中炼铁项目169个,减少51个;项目287个,减少71个;钢加工项目1581个,减少93个。产能盲目扩张态势得到明显遏制。\n\n(七)节能环保再上新台阶,主要污染物排放和能源消耗指标均有所下降。2014年,钢铁行业全面推广烧结脱硫、能源管控等节能减排技术,节能环保效果明显。重点大中型企业吨钢综合能耗同比下降1.2%,总用水量下降0.6%,吨钢耗新水下降0.5%,外排废水总量下降5%,二氧化硫排放下降16%,烟粉尘排放下降9.1%。\n\n(八)新技术、新产品开发取得突出进步,有力支撑我国装备制造业和重大工程发展。2014年,钢铁企业技术创新步伐进一步加快,宝钢BW300TP新型耐磨钢成功用于中集集团搅拌车的生产,使机械服役寿命延长两倍以上;鞍钢核反应堆安全壳、核岛关键设备及核电配套结构件三大系列核电用钢在世界首座第三代核电项目CAP1400实现应用;武钢无取向硅钢应用于全球单机容量最大的向家坝800兆瓦大型水轮发电机;太钢生产的最薄0.02毫米的精密带钢产品,填补了国内高端不锈钢精密带钢产品空白;宝钢牵头的“600℃超超临界火电机组钢管创新研制与应用”获得国家科技进步一等奖。\n\n二、新常态下我国钢铁工业发展中的突出问题\n\n(一)产能依然过剩,企业效益两极分化。截至2014年底,我国粗钢产能已达11.6亿吨,仍处于较高水平。从企业效益看,重点大中型企业中实现利润前20名企业总体盈利280亿元,占行业利润总额的92%;亏损企业19家,累计亏损116亿元,企业盈利水平两极分化严重。\n\n(二)企业财务状况未得到有效改善,银行抽贷、融资贵问题突出。2014年,重点大中型钢铁企业资产负债率为68.3%,同比下降0.8个百分点,但与行业效益最好的2007年相比高出11个百分点。受银行系统严控产能过剩行业和钢贸企业信贷规模影响,银行提高了钢铁行业贷款利率,2014年重点大中型钢铁企业财务费用共计938.3亿元,同比增长20.6%,是企业实现利润的3倍多。部分银行对企业采取了大额抽贷、压贷,已有钢铁企业因此出现停产甚至破产情况。\n\n(三)产业集中度降低,同质化竞争进一步向高端产品蔓延。近年来钢铁行业效益不佳,企业兼并重组意愿下降。2014年,粗钢产量前10家企业产量占全国总产量的36.6%,同比下降2.8个百分点。大型钢铁企业精品板材项目多为汽车板、电工钢等高端产品,已出现过剩迹象,低牌号取向电工钢、无取向电工钢及普通质量汽车板市场压力进一步加大,高端产品同质化竞争日趋加剧。\n\n(四)出口产品大幅增加,引发贸易摩擦冲突加剧。2014年,我国出口钢材占全球钢铁贸易量的32.2%,创历史最高水平。其中含硼钢前11个月累计出口3976万吨,占当期的47.5%左右,多个国家对我国钢材产品采取贸易保护措施。2014年国外对我钢铁企业发起的贸易救济措施调查达到40起,且发起调查国家除原有的欧美发达国家,又增加了亚洲、非洲、拉美发展中国家,范围逐步扩大。\n\n(五)地条钢、无票销售现象扰乱钢材市场,市场公平竞争亟需解决。受行业不景气影响,部分中小企业采取生产地条钢、无票销售等违法违规手段获取市场份额和利润,严重扰乱了市场公平竞争环境,不仅挤压了正规经营企业市场空间,也为落后产能提供了生存空间,不利于行业健康发展。\n\n三、2015年钢铁行业发展形势展望\n\n整体看来,2015年钢材供过于求的现状难以好转、出口将略有降低、钢材价格仍将地位徘徊、钢厂盈利状况难言乐观,钢材市场将依然弱势运行。\n\n(一)我国经济发展步入新常态,产业结构调整和优化速度将加快。我国经济已经进入中高速发展的新常态,经济发展方式从规模速度型粗放增长转向质量效率集约增长,经济结构从增量扩能为主转向调整存量、做优增量并存的深度调整。新常态下我国钢铁消费已进入峰值弧顶区,消费的质量和个性化需求越来越高,钢铁行业由原来的依靠数量扩张和价格竞争逐步向依靠质量、差异化竞争转变。新常态为钢铁行业产业转型发展提供了外部空间和发展动力,结构调整步伐将进一步加快。\n\n(二)国内投资增速下滑,钢铁下游需求短期难有较大改观。2014年全国固定资产投资增速为2002年以来的最低值。在我国经济增长模式发生深刻转变的背景下,预计2015年固定资产投资增速将进一步降低,钢材需求难有较大改观。但也应该看到,“一带一路”、京津冀协同发展、长江经济带等国家重点战略将对钢材需求起到一定的拉动作用。\n\n(三)钢铁产能惯性增加,化解产能过剩任重道远。虽然2014年我国黑色金属冶炼及压延业投资下降5.9%,但仍处于相对高位,钢铁工业新开工项目仍有2037个,同时考虑前期建设项目产能的惯性增长,2015年全国粗钢产能规模仍有增长的可能。\n\n(四)新环境保护法实施,钢铁企业环保压力将加大。新颁布的《中华人民共和国环境保护法》于2015年开始实施。根据钢铁工业实际投资情况,要达到国家新排放标准,初步估算吨钢环保投资需增加13%,吨钢运营费用约增加200元,较实施前增加40%左右。新环保法的实施将督促企业加大环保投入,促进企业技术创新。\n\n(五)出口退税政策调整,钢材出口略有下降。2015年,国家取消含硼钢出口退税将在一定程度上抑制低附加值钢材产品出口,但与日、韩、德等发达国家相比,我国钢材具有价格优势,国内过剩产能会积极寻求出口,预计2015年我国钢材出口总量仍将维持在较高水平。\n\n四、2015年保持钢铁行业持续稳定发展思路\n\n2015年钢铁行业要紧紧抓住全面深化改革和推进经济结构战略性调整的历史机遇,坚持以提高质量和效益为核心,适应经济新常态,力争在营造公平竞争市场环境、推进钢铁产能严重过剩矛盾化解、促进两化深度融合、提升钢铁行业竞争力和企业效益方面取得新进展。\n\n(一)完善钢铁行业规范管理\n\n钢铁行业规范管理工作是加强和改善行业管理,进行事中事后监管的有效尝试,效果显著。在已公告305家规范企业的基础上,工业和信息化部将重新修订《钢铁行业规范条件》,加强节能环保等标准约束;配套出台《钢铁行业规范企业管理办法》,对已公告的规范企业开展动态管理。同时,建设规范企业信息综合数据库,为规范管理提供信息支撑。\n\n(二)推进钢铁行业两化融合\n\n根据《原材料工业两化深度融合推进计划(2015-2018年)》(工信部原[2015]25号)总体安排,2015年工业和信息化部将着力推进钢铁行业两化融合,开展智能工厂应用示范,推动并制修订一批两化融合标准,支持大型钢铁企业自有电子商务平台向行业开放平台转化,推动汽车板、造船板等个性化订单加工配送。\n\n(三)加强行业规划引导\n\n结合编制中的《中国制造强国2025规划发展纲要》,为促进钢铁工业由大到强,2015年工业和信息化部将制定发布《钢铁工业转型发展行动计划》,进一步推动落实有关配套政策措施;同时将适时发布《铁矿行业中长期发展规划(2010-2025)》,引导我国铁矿行业持续健康发展。\n\n(四)继续推进钢铁产能过剩矛盾化解\n\n进一步贯彻落实《国务院关于化解产能严重过剩矛盾的指导意见》(国发[2013]41号),做好2015年淘汰落后任务的下达和监督检查工作。积极维护公平竞争的市场环境,会同质检、工商、发改等部门开展打击地条钢专项行动。以新环保法实施为契机,会同相关部门加强事中事后监管,倒逼过剩产能退出市场。\n\n(五)推进上下游产业协作\n\n依托我部已经建立的协调工作机制,继续推进高强钢筋、高性能电工钢、船舶和海工用钢的推广应用,促进标准制修订,推动船用钢材加工配送。推动解决国产高端耐磨钢等钢材产品推广过程中遇到的政策障碍及市场瓶颈问题。'),
(4, '台泥、亚泥去年并购表现利于西进大陆市场', '2015-03-11', '行业新闻', '2015年，因台泥、亚泥2014年都有逾500万吨产能并购，市场相信，对水泥产业来说，今年营运绩效仍抱乐观看待，预期会是丰收的好年冬。此外，大陆国家标准化管委会宣布，2015年12月起将取消32.5等级低端水泥生产，这对西进水泥厂大陆市场业绩有加分。', '国内水泥产业因环保政策、公共工程市场成熟，近几年来，台湾市场每年都以稳健、不到5％的幅度成长；但受惠大陆市场获利成长贡献下，包括台泥、亚泥及国产建材实业等西进水泥厂，2014年整体财报营运，表现都比2013年好。\n\n2015年，因台泥、亚泥2014年都有逾500万吨产能并购，市场相信，对水泥产业来说，今年营运绩效仍抱乐观看待，预期会是丰收的好年冬。此外，大陆国家标准化管委会宣布，2015年12月起将取消32.5等级低端水泥生产，这对西进水泥厂大陆市场业绩有加分。\n\n而全球油价崩盘，也让水泥生产使用最多的原料煤价抬不了头；大陆煤炭价格恐慌性降价将延续到今年，水泥业生产成本可望续降。\n\n台泥 饱赚 淡季不淡\n\n台泥（1101）2014年大陆市场赚逾20亿元人民币，创西进以来高峰；今年，并购四川铁道、金大地等两家水泥厂后，2015年集团在大陆水泥业总产能已逾6,000万吨。而原物料采集体采购，成本降低，加上处理生活垃圾订单量增加，预期2015年上半年可望是「淡季不淡」，全年则有机会获利会再创新高。\n\n亚泥 并进陆十大厂\n\n亚泥（1102）去年第2季，完成并购兰丰水泥厂，在大陆的水泥产能也已接近3,000万吨。持续在华中地区扩充上下游整合实力，预期今年毛利率可望提升1-2个百分点。另，继续购进大陆山水水泥股权，由于山水水泥是大陆前五大水泥厂，主要市场在东北及华北地区，今年是否有机会跨出原本经营的华中地区市场，扩大营业范围、增加产能，让2015年的营运绩效晋身为中国大陆前10大水泥厂之林。\n\n国产 将跳跃式成长\n\n国产建材实业（2504）进行预拌混凝土产业上中下游一条龙垂直整合，今年，大陆水泥厂和华润集团合作；预拌混凝土则进行港口、船队、砂石山的购进整合；下游则以土地资产活化、商场及饭店事业版图的多元发展，市场预期，2015年会是跳跃式成长的一年，除毛利率有机会提升到2位数外，整体的营收成长空间也会加大到2成上下，市场及法人对今年营运业绩看好，有机会成近10年来获利最好的一年。'),
(5, '江苏南京江南小野田和中国水泥厂年内关停', '2015-03-11', '行业新闻', '按计划，江南小野田将在今年6月份左右关停，中国水泥厂将于今年年底关停。', '“江南小野田今年6月份左右关停、中国水泥厂年底关停！”南京市栖霞区在清理污染企业，推动企业转型升级的道路上向前迈了一大步。记者近日从“迈上新台阶、建设新南京”系列活动中了解到，金陵石化烷基苯厂等4家大型污染企业的“搬迁协议”也将于年内签订。\n\n栖霞区发改局局长孔毅远说，该区在过去几十年中因为发展经济而给环境造成了沉重负担。在今年的南京市两会期间，缪瑞林市长在政府工作报告中明确提出，要加强生态文明建设，营造优美宜居环境。全面实施“保、调、减、退、提”生态环境倒逼策略，一手抓保护建设，一手抓污染治理，促进生态环境持续改善。此后，栖霞区加快了“啃骨头”的速度。而“难啃的骨头”中就包括中国水泥厂和江南小野田这两家大型水泥企业。\n\n早在2013年，南京市政府就曾发文，要求关停这两家大型水泥厂，但是一直以来困难重重。“今年是十二五规划的完成年，再难啃的骨头也要啃下。”据孔毅远透露，中国水泥厂和江南小野田的关停工作正在有序推进过程中。按计划，江南小野田将在今年6月份左右关停，中国水泥厂将于今年年底关停。\n\n随着“退城入园”计划的顺利实施，栖霞区两年内计划搬迁的21家企业大部分已经停产、搬迁，目前还没有将原厂址关停的企业只剩8家。这8家企业主要集中在丁家庄保障房周边，这些企业也将尽快退出主城范围。此外，备受关注的金陵石化的烷基苯厂及周边江苏金桐、南京金桐、佳和日化等4家大型企业的整体搬迁工作也有了新进展。“我们将尽快拿出这4家企业的搬迁方案，年内签订搬迁协议，时间表、路线图、责任人一个都不能少。”孔毅远介绍说。\n\n近年来，栖霞区加快转型发展。据介绍，栖霞区转型有两大法宝。一是做“减法”：淘汰落后产能，累积整治燕子矶、迈皋桥等地区200家“三高两低”企业，2014年关闭200家落后企业；二是做“加法”：提高互联网新兴产业比重，重点发展光电显示、生物医药、智能制造等“三大”科技产业。据了解，从2012年至今，栖霞区已经关停、搬迁240多家污染性企业，涉及到的劳动就业人口达23000人左右，涉及到的产值达20亿元，税收2个亿。花这么大的代价，栖霞区就是要表明一个态度：既要金山银山，更要绿水青山，给子孙后代留一片蓝天。'),
(6, '四年来首个核电新项目核准', '2015-03-11', '行业新闻', '红沿河核电厂二期项目全面满足中国最新核安全要求', '中电新闻网讯 记者 龙昌 报道 3月10日，记者从中国广核集团了解到，国家发展改革委发布文件，确定红沿河核电厂二期项目两台百万千瓦核电机组已获核准。这是4年来我国真正意义上新批的核电项目。据介绍，红沿河核电二期项目将采用ACPR1000机型，该机型主要指标符合三代核电标准。\n\n2011年以来我国没有新的核电项目获批，期间少数新开工建设项目为2011年3月之前核准，且满足《福岛核事故后核电厂改进行动通用技术的要求（试行）》，安全标准大幅提高。红沿河核电二期项目在2011年3月前已经完成了多项核准前准备工作，因此红沿河核电二期项目有其特殊性，被当成历史遗留问题处理。2014年以来，国家领导人多次强调，要抓紧启动东部沿海地区新的核电项目建设，开工建设一批沿海核电项目。国务院2014年8月8日出台的《关于近期支持东北振兴若干重大政策举措的意见》中，明确提出要“优化东北地区能源结构，开工建设辽宁红沿河核电二期项目”。此次获得国家核准，意味着红沿河核电二期项目成为4年来我国真正意义上的新批核电项目，对于现阶段我国核电发展意义重大。\n\n全国政协委员、中国广核集团董事长贺禹告诉记者，ACPR1000机型是中广核在几十年核电建设运营经验基础上，坚持自主创新，按照国际最新安全标准，借鉴国际核电领域的最新经验反馈，基于成熟堆型实施改进形成的自主化百万千瓦级压水堆机型，该机型具备三代核电主要安全技术特征，堆芯熔化概率和放射性释放概率控制达到国际领先水平，全面满足中国最新核安全要求，是安全可靠的。\n\n红沿河核电站是目前东北地区唯一一座核电站，一期工程中的1、2号机组已并网发电，3、4号机组处于建设期。红沿河核电站的业主公司红沿河核电有限公司由中国广核集团公司、中国电力投资集团公司和大连市建设投资公司按照45 ∶45∶10的比例出资。'),
(7, '我国轴承产业大而不强 需加强技术研发投入', '2015-01-10', '产品新闻', '我国轴承产业大而不强 需加强技术研发投入。据悉，在轨道交通、医疗器械、新能源、航空航天、汽车轻量化，轨道交通等各个领域发展的带动下，我国轴承铸造行业水平明显得到了提高。轴承铸造行业在传统市场稳部前进的同时积极开拓新兴市场，甚至是过去被忽略的边缘市场也得到了开发。', '我国作为全球范围内的制造业大国，很多行业的生产规模都位居前列，但是也只是规模大而已，在技术含量上并不高，产业始终处于大而不强，不上不下的尴尬地位。\n\n国内轴承铸造产业肩负着我国高端装备国产化的重要使命，在“十二五”规划的指导下，我国的轴承铸造行业制定了行业发展的规划。制订了以项目和出口两驾马车拉动国内模具业的发展的方针。\n\n据悉，在轨道交通、医疗器械、新能源、航空航天、汽车轻量化，轨道交通等各个领域发展的带动下，我国轴承铸造行业水平明显得到了提高。轴承铸造行业在传统市场稳部前进的同时积极开拓新兴市场，甚至是过去被忽略的边缘市场也得到了开发。根据相关规划，“十二五”期间,高铁将迎来建设高峰，2011年全国铁路计划基建投资7000亿元人民币，为整个高铁设备制造企业提供了巨大的市场机遇。根据《中长期铁路网规划(2008年调整)》，到2012年我国将建成42条高铁客运专线，总里程将超过1.3万公里，这对动车组将形成800列的新增需求，到2020年我国高速铁路里程将达1.8万公里，为我国高铁轴承提供了广阔的市场空间。\n\n业内有关专家估算，未来三年我国高铁轴承市场将超过20亿元。但理财一周报调查发现，作为高铁基础零配件的高速列车轴承领域，却是瑞典SKF、德国FAG、日本NTN等国际巨头在牢牢占据着中国的市场。有关人士表示，轴承是国家重大技术装备的关键零部件，目前轿车、高铁、风电、精密机床主轴配套轴承等高端轴承一直是中国轴承行业的软肋，长期依靠进口。由于我国轴承工业发展跟不上，强力拉动了轴承的进口。如在高速铁路的大发展中，时速200公里以上的动车组用轴承全部为进口，国内目前能满足只是160公里左右的机车轴承。有关人士表示，虽然少部份国内企业可以制造业时速200公里级别的动车轴承，但相关采购部门还是会采用进口部件，我国高端轴承领域前景堪忧。'),
(8, '斯凯孚（SKF）助力金通灵推出磁浮高速鼓风机', '2014-12-13', '产品新闻', '斯凯孚（SKF）助力金通灵推出磁浮高速鼓风机，帮助用户提高污水处理能效及可靠性', '江苏南通，2014年12月12日：国内著名的鼓风机制造商江苏金通灵流体机械股份有限公司今日正式推出了用于污水处理设施的磁浮高速鼓风机。相比传统齿轮箱增速的高速鼓风机，通过使用斯凯孚（SKF）高速永磁磁浮电动机解决方案，该磁浮高速鼓风机效率至少提高9%，并能够大幅提高维修间隔时间（ MTBF）\n\n斯凯孚高速永磁磁浮电动机解决方案包括输出功率为75千瓦-350千瓦的高速永磁磁浮电机（PMM）、有源磁性轴承（AMB）和磁浮轴承控制系统（MBC）。在传统废水设施中，通气鼓风机系统需要消耗工厂总能源用量的40%至80%，而PMM能够在部分载荷和半速运行时仍然保持极高的效率，大大降低了能耗。高速永磁磁浮电动机所使用的机械零部件少于传统的驱动系统，这有助于提高维修间隔时间。更重要的是，磁浮系统高速、无油、无接触、无摩擦、无磨损的特点，可以使整个风机系统结构更紧凑，在运行过程中除了更换空气过滤器，无需其它维护。同时，斯凯孚先进及成熟的磁浮轴承控制技术，可以实时监控和调整转子的位置，使风机时时处于最佳运行状态，这些都大大提高了设备运行的可靠性和维修间隔时间（MTBF）。\n\n作为金通灵的战略合作伙伴，除了不断提供先进的产品和解决方案，斯凯孚始终致力于利用在行业内的知识和经验帮助金通灵提高生命周期管理的能力。当获悉金通灵希望在既有的压缩机技术基础上开发新型的磁浮高速鼓风机时，斯凯孚不仅提供了已获得广泛认可的S2M磁浮轴承，更与金通灵分享了在磁浮高速电机方面的先进技术和丰富的应用经验。双方自2012年进行了首次沟通，在对成本和市场进行评估分析后，顺利达成了合作协议。此后，斯凯孚和金通灵历时两年进行新产品设计、开发、制造等，并于2014年9月测试成功，电机效率达到97.2%，金通灵的磁悬浮330kw风机系统效率达到81.3%。\n\n斯凯孚中国工业传动业务部销售总监龚荣蓉表示：“通过装载斯凯孚高速永磁电动机，金通灵磁浮高速鼓风机能够有效提高能效以及可靠性并减少维护成本。将行业知识、全球化经验和技术平台相结合，为客户创造价值，这正是我们所说的‘知识工程的力量’。相信金通灵的成功只是开始，斯凯孚高速永磁电动机解决方案将不断为本地客户带来价值。”\n\n斯凯孚高速永磁电动机解决方案已在欧洲市场取得了巨大成功。在最近的一个成功案例中，法国一家废水处理厂通过使用斯凯孚高速永磁电动机解决方案，大幅减少了能源使用和二氧化碳排量。该厂为当地一座10万人口的城市提供服务，它的四台80 kW叶片型通气鼓风机发生了频繁的停工、高能源用量、高噪声和处理工艺问题。当工厂以两台配备斯凯孚高速永磁电动机解决方案的新型离心鼓风机替换叶片型风机后，噪声水平立刻从110 dBA降低至70 dBA。运行一年后，该厂运营成本降低了54,000欧元，二氧化碳排放量减少了375吨。'),
(9, '我国将扩大节能环保产品出口', '2014-05-08', '行业新闻', '国务院办公厅日前发布《关于促进外贸稳定增长的若干意见》，明确了扩大技术和资金密集型的机电产品、高技术高附加值产品和节能环保产品的出口。支持企业技术改造，提高劳动密集型产品的出口质量', '国务院办公厅日前发布《关于促进外贸稳定增长的若干意见》，明确了扩大技术和资金密集型的机电产品、高技术高附加值产品和节能环保产品的出口。支持企业技术改造，提高劳动密集型产品的出口质量、档次和附加值。控制高耗能、高污染的产品出口。\n\n意见提出，规范和减少进出口环节收费。认真落实取消出口收汇核销单、进口付汇单、出口报关单退税联打印费用的规定，取消海关监管手续费。自今年10月1日起至12月31日，对所有出入境货物、运输工具、集装箱及其他法定检验检疫物免收出入境检验检疫费。明年1月1日起，执行新的降低后的检验检疫收费标准。\n\n意见提出，逐步扩大一般贸易比重。引导加工贸易从沿海向内陆地区转移和向海关特殊监管区域集中，鼓励加工贸易企业延伸产业链、增值链，提高本地增值和本地配套的比重。 (文怡)'),
(10, '机电产品输欧需谨防“小问题”', '2014-05-08', '行业新闻', '今年上半年，欧盟针对中国共发布了不安全产品召回通报499批次，其中涉及机电产品116批次，主要包括各类充电物品、灯具、插头等小家电，通报原因尤以违反EN60598、EN60335、', '今年上半年，欧盟针对中国共发布了不安全产品召回通报499批次，其中涉及机电产品116批次，主要包括各类充电物品、灯具、插头等小家电，通报原因尤以违反EN60598、EN60335、EN60950等协调标准最为集中，表现为违反LVD低电压指令、绝缘不佳、爬电距离短、耐热防水性能差等看似不影响使用的“小问题”。\n\n宁波是我国小家电的重要生产和出口基地，今年1月至6月，宁波地区出口至欧盟的小家电总计16421批，5.48亿美元，相比去年同期分别增长 8.48%、10.23%。但是小家电质量问题层出不穷也是一个久治不愈的顽疾，一定程度上影响着中国产品“物美价廉”的良好声誉。\n\n对此，专家提醒相关企业要密切关注欧盟等国对产品安全标准的动态变化，及时做好标准升级工作;务必加强企业上下的产品安全意识，在生产或组建电器类产品时，必须严格按照出口国相关标准，不一味追求低成本或直接忽视材料安全，对产品的隔热绝缘低压等细节问题加强技术管控;遵照出口国标准要求，对产品潜在风险作出相应警示标记;提高试验测试标准水平，主动进行产品认证，在自身技术水平受限情况下可寻求政府相关部门或其他权威机构对产品各种安全指标进行检测，切不可因产品某个环节上的“小问题”最终丢了大订单。 (章 莹)'),
(11, '旧机电产品进口数量增隐患多', '2014-05-08', '行业新闻', '今年上半年，山东青岛检验检疫局共完成进口旧机电产品检验检疫199批、货值2899.67万美元，与去年同期相比批次增长9.34%、货值增长 178.56%。其中检验不合格22批、货值', '今年上半年，山东青岛检验检疫局共完成进口旧机电产品检验检疫199批、货值2899.67万美元，与去年同期相比批次增长9.34%、货值增长 178.56%。其中检验不合格22批、货值328.86万美元，分别占全省系统进口旧机电产品不合格总量和货值的23.91%和23.68%，不合格产品主要来源于韩国、日本、美国和新加坡。\n\n进口旧机电产品不合格原因主要有6个方面。一是机械安全隐患。主要表现为设备的动力和机械传动部位缺少安全警示标志;机械危险处无防护装置或安装位置不合理、防护距离不达标、防护措施不足等。二是电气安全隐患。主要表现为安全警示颜色使用不当，紧急停车按钮无黄色警示衬底或磨损严重，甚至丧失功能等。三是卫生隐患。主要表现为存在废渣油污、卫生状况差等。四是环保隐患。主要表现为进口旧设备工作时噪声超过规定的限值。五是能耗隐患。一些欧美国家和地区的旧机电耗能高，不利于节能减排。六是欺诈隐患。主要表现为到货产品规格型号、生产日期、制造商、产地等与备案文件不一致;对旧设备进行重新喷涂，更换零件、外壳来“以旧充新”逃避装运前检验。\n\n对此，检验检疫部门建议，通过加强前期论证，提高产品引进合理性;探索建立“诚信体系建设+风险问题评估+进口分类管理”的监管新模式，提高检验监管针对性;注重境外把关，严格执行装运前检验制度，提高检验监管前瞻性;强化与海关、商务等部门协作，提高执法把关有效性。'),
(12, '本网开通 寄语祝福 传递价值 共创辉煌', '2013-11-18', '公司新闻', '本网开通 寄语祝福 传递价值 共创辉煌', '益如驰机电官方网站www.oneruchi.com开通了！喜讯就像插上了翅膀，在网络上飞速传播。借此真心感谢所有的同事，感谢与这一群热爱生活热爱工作的同事们一起努力、一起拼搏，谢谢你们。\n\n希望网站的开通能让更多的客户了解到益如驰科技的信息、产品和服务，能为客户带来价值。'),
]

